Definition rd_exit_model (msv1 tl : Z) (s : rstate) : res (list Z * Z * Z * Z) :=
  if negb (r_remaining s =? 1) then Err ZSTD_error_corruption_detected
  else if msv1 <? r_charnum s then Err ZSTD_error_maxSymbolValue_tooSmall
  else if 32 <? r_bitCount s then Err ZSTD_error_corruption_detected
  else Ok (r_nc s, r_charnum s - 1, tl, r_ip s + Z.shiftr (r_bitCount s + 7) 3).

Definition rd_res_ok (C : rdctx) (m' : fmem) (r : Z) (R : res (list Z * Z * Z * Z)) : Prop :=
  0 <= r < 2^64 /\
  match R with
  | Ok (rt, msv, tl, n) => r = n /\ u8arr usegs m' (c_NC C) (u16s (map (Z_to_bv 64) rt))
                           /\ rw_cells usegs m' (c_MSVP C) [C4 (Z_to_bv 64 msv)] /\ rw_cells usegs m' (c_TLP C) [C4 (Z_to_bv 64 tl)]
  | Err e => r = 2^64 - e /\ 0 < e < 120
  | Ub | NoFuel => False
  end.

Definition rd_body_posth (C : rdctx) (R : res (list Z * Z * Z * Z)) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (r : Z) (m' : fmem),
    ms' = MS (mkR (c_ra C) (Z_to_bv 64 (c_SP C)) (c_gp C) (c_tp C) t0 t1 t2 (c_s0 C) (c_s1 C) (Z_to_bv 64 r) a1 a2 a3 a4 a5 a6 a7
                 (c_s2 C) (c_s3 C) (c_s4 C) (c_s5 C) (c_s6 C) (c_s7 C) (c_s8 C) (c_s9 C) (c_s10 C) (c_s11 C) t3 t4 t5 t6)
             (c_F C) (ret_pc (c_ra C)) (c_fc C) None m' (seg_rom usegs)
    /\ munch (rd_W C) (c_m C) m'
    /\ wmono usegs (c_m C) m' /\ mem_inv usegs m'
    /\ stk usegs m' (c_lo C) (c_SP C)
    /\ rd_res_ok C m' r R.

