(* [comment removed for export] *)
Lemma body8_eq : forall buf msv1 nc0, 8 <= zlen buf -> msv1 <= zlen nc0 ->
  read_ncount_body8 buf msv1 nc0 =
    if 10 <? Z.land (le32 buf 0) 15 then Err ZSTD_error_tableLog_tooLarge
    else (let! s := rloop buf msv1 (S (Z.to_nat msv1)) (rd_s0 buf msv1 nc0) in
          rd_exit_model msv1 (Z.land (le32 buf 0) 15 + 5) s).
Proof.
